python3 - <<'EOF'
import sys, traceback

# ---- module under test ----
exec(open("orders.py").read(), (ns := {}))
create = ns["create"]
update = ns["update"]
_validate_qty = ns["_validate_qty"]

failures = []

# test_create
try:
    assert create(2) == {"qty": 2}
    print("PASS test_create")
except Exception as e:
    failures.append(f"FAIL test_create: {e}")

# test_update_rejects_zero
try:
    try:
        update({"qty": 1}, 0)
        failures.append("FAIL test_update_rejects_zero: no ValueError raised")
    except ValueError:
        print("PASS test_update_rejects_zero")
except Exception as e:
    failures.append(f"FAIL test_update_rejects_zero: {e}")

# bonus: helper deduplication — create also rejects zero
try:
    try:
        create(0)
        failures.append("FAIL create_rejects_zero: no ValueError raised")
    except ValueError:
        print("PASS create_rejects_zero")
except Exception as e:
    failures.append(f"FAIL create_rejects_zero: {e}")

if failures:
    for f in failures:
        print(f)
    sys.exit(1)
print("\nAll tests passed.")
EOF
